mapper.select:
SELECT ai.indicator_id, ai.indicator_name, ROUND(AVG(ad.score), 2) as averageScore, ROUND(MAX(ad.score), 2) as maxScore, ROUND(MIN(ad.score), 2) as minScore, ROUND(AVG(CASE WHEN ad.actual_value >= ad.target_value THEN 100 ELSE 0 END), 2) as achievementRate, COUNT(*) as totalCount, COUNT(CASE WHEN ad.score >= 90 THEN 1 END) as excellentCount, COUNT(CASE WHEN ad.score >= 80 AND ad.score < 90 THEN 1 END) as goodCount, COUNT(CASE WHEN ad.score >= 70 AND ad.score < 80 THEN 1 END) as averageCount, COUNT(CASE WHEN ad.score >= 60 AND ad.score < 70 THEN 1 END) as qualifiedCount, COUNT(CASE WHEN ad.score < 60 THEN 1 END) as unqualifiedCount FROM assessment_detail ad LEFT JOIN assessment_indicator ai ON ad.indicator_id = ai.id LEFT JOIN project_assessment pa ON ad.assessment_id = pa.id WHERE pa.assessment_period = #{assessmentPeriod} AND pa.assessment_status >= 2
AND ad.indicator_id = #{indicatorId}
GROUP BY ai.indicator_id, ai.indicator_name ORDER BY ai.sort_order ASC, ai.id ASC

mapper.insert:
INSERT INTO assessment_detail (
    assessment_id, indicator_id, actual_value, target_value, score, weight,
    weighted_score, data_source, calculation_formula, remarks, create_time, create_by
) VALUES

    (
        #{item.assessmentId}, #{item.indicatorId}, #{item.actualValue}, #{item.targetValue},
        #{item.score}, #{item.weight}, #{item.weightedScore}, #{item.dataSource},
        #{item.calculationFormula}, #{item.remarks}, #{item.createTime}, #{item.createBy}
    )

mapper.select:
SELECT CASE WHEN ad.score >= 90 THEN '90-100' WHEN ad.score >= 80 THEN '80-89' WHEN ad.score >= 70 THEN '70-79' WHEN ad.score >= 60 THEN '60-69' ELSE '0-59' END as scoreRange, COUNT(*) as count FROM assessment_detail ad LEFT JOIN project_assessment pa ON ad.assessment_id = pa.id WHERE ad.indicator_id = #{indicatorId} AND pa.assessment_status >= 2
AND pa.assessment_date >= #{startDate}
AND pa.assessment_date <= #{endDate}
GROUP BY CASE WHEN ad.score >= 90 THEN '90-100' WHEN ad.score >= 80 THEN '80-89' WHEN ad.score >= 70 THEN '70-79' WHEN ad.score >= 60 THEN '60-69' ELSE '0-59' END ORDER BY CASE WHEN ad.score >= 90 THEN 1 WHEN ad.score >= 80 THEN 2 WHEN ad.score >= 70 THEN 3 WHEN ad.score >= 60 THEN 4 ELSE 5 END
